#!/usr/bin/env node
/**
 * Cude.new - regenerate the tracked product-quality showcase.
 *
 * `verification-showcase/` is a committed artifact that other checks read: the
 * export test packages it, and the screenshot pass serves its build. It is
 * supposed to be an example of what Cude produces.
 *
 * It is therefore generated by the product's own modules. This script used to
 * carry a plain-JS replica of the design system and the project generator, so
 * the committed fixture was the replica's output rather than the product's —
 * which meant every check reading it was measuring the wrong thing.
 */
import fs from 'node:fs';
import path from 'node:path';
import { loadCudeModules, REPO_ROOT } from './lib/load-cude.mjs';

const OUT_DIR = path.join(REPO_ROOT, 'verification-showcase');

const PROMPT = `Build a polished personal finance application with:
1. Dashboard
2. Transactions
3. Analytics
4. Settings
The product should feel precise, premium and trustworthy.
It should be responsive and use one coherent visual language across every screen.`;

const { createDesignSystem, financeVerificationFiles } = await loadCudeModules([
  'app/lib/cude/designSystem.ts',
  'app/lib/cude/verificationProject.ts',
]);

const ds = createDesignSystem(PROMPT);
const files = financeVerificationFiles(PROMPT, ds);

/*
 * Only the generated sources are replaced. node_modules and dist are ignored
 * by git and expensive to rebuild, so they are left where they are.
 */
for (const entry of fs.existsSync(OUT_DIR) ? fs.readdirSync(OUT_DIR) : []) {
  if (entry === 'node_modules' || entry === 'dist') {
    continue;
  }

  fs.rmSync(path.join(OUT_DIR, entry), { recursive: true, force: true });
}

for (const [relative, contents] of Object.entries(files)) {
  const absolute = path.join(OUT_DIR, relative);
  fs.mkdirSync(path.dirname(absolute), { recursive: true });
  fs.writeFileSync(absolute, contents, 'utf8');
}

console.log(`Wrote ${Object.keys(files).length} files to verification-showcase/`);
console.log(`Design system: ${ds.meta.preset} v${ds.meta.version}, radius-md ${ds.radius.md}`);
